#[cfg(test)]
#[test]
#[allow(non_snake_case)]
fn __rt_Int128() {
    samples::__stack(move || {
        let v = samples::s_Int128(3);
        let mut out = Vec::new();
        v.store_boxed(&mut out);
        let w = Int128::parse(&out).expect("Int128 parse");
        assert_eq!(v, w);
        let mut out = Vec::new();
        v.store(&mut out);
        let w = Int128::parse_bare(&out).expect("Int128 bare parse");
        assert_eq!(v, w);
    });
}

